                "error.503.mandate_unavailable" to ErrorSpec(ErrorCode("error.503.mandate_unavailable"), 503, listOf(), Remediation.Retry, "Cannot verify workspace mandate right now"),
                "error.503.verification_unavailable" to ErrorSpec(ErrorCode("error.503.verification_unavailable"), 503, listOf(), Remediation.WaitAndRetry, "We could not check your sign-in right now. Please try again in a moment."),
            )

    override fun spec(code: ErrorCode): ErrorSpec? = specs[code.value]

    override fun template(code: ErrorCode, locale: LocaleTag): String? = if (locale.value == "en") specs[code.value]?.en else null
}
